template <typename UnionPtrType>
BluetoothPropertyPtr BluetoothProperty::Clone() const {
  switch (tag_) {
    case Tag::kBdname:
      return NewBdname(
          mojo::Clone(*data_.bdname));
    case Tag::kBdaddr:
      return NewBdaddr(
          mojo::Clone(*data_.bdaddr));
    case Tag::kUuids:
      return NewUuids(
          mojo::Clone(*data_.uuids));
    case Tag::kDeviceClass:
      return NewDeviceClass(
          mojo::Clone(data_.device_class));
    case Tag::kDeviceType:
      return NewDeviceType(
          mojo::Clone(data_.device_type));
    case Tag::kServiceRecord:
      return NewServiceRecord(
          mojo::Clone(*data_.service_record));
    case Tag::kAdapterScanMode:
      return NewAdapterScanMode(
          mojo::Clone(data_.adapter_scan_mode));
    case Tag::kBondedDevices:
      return NewBondedDevices(
          mojo::Clone(*data_.bonded_devices));
    case Tag::kDiscoveryTimeout:
      return NewDiscoveryTimeout(
          mojo::Clone(data_.discovery_timeout));
    case Tag::kRemoteFriendlyName:
      return NewRemoteFriendlyName(
          mojo::Clone(*data_.remote_friendly_name));
    case Tag::kRemoteRssi:
      return NewRemoteRssi(
          mojo::Clone(data_.remote_rssi));
    case Tag::kRemoteVersion:
      return NewRemoteVersion(
          mojo::Clone(*data_.remote_version));
    case Tag::kLocalLeFeatures:
      return NewLocalLeFeatures(
          mojo::Clone(*data_.local_le_features));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, BluetoothProperty>::value>::type*>
bool BluetoothProperty::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kBdname:
      return mojo::Equals(*(data_.bdname), *(other.data_.bdname));
    case Tag::kBdaddr:
      return mojo::Equals(*(data_.bdaddr), *(other.data_.bdaddr));
    case Tag::kUuids:
      return mojo::Equals(*(data_.uuids), *(other.data_.uuids));
    case Tag::kDeviceClass:
      return mojo::Equals(data_.device_class, other.data_.device_class);
    case Tag::kDeviceType:
      return mojo::Equals(data_.device_type, other.data_.device_type);
    case Tag::kServiceRecord:
      return mojo::Equals(*(data_.service_record), *(other.data_.service_record));
    case Tag::kAdapterScanMode:
      return mojo::Equals(data_.adapter_scan_mode, other.data_.adapter_scan_mode);
    case Tag::kBondedDevices:
      return mojo::Equals(*(data_.bonded_devices), *(other.data_.bonded_devices));
    case Tag::kDiscoveryTimeout:
      return mojo::Equals(data_.discovery_timeout, other.data_.discovery_timeout);
    case Tag::kRemoteFriendlyName:
      return mojo::Equals(*(data_.remote_friendly_name), *(other.data_.remote_friendly_name));
    case Tag::kRemoteRssi:
      return mojo::Equals(data_.remote_rssi, other.data_.remote_rssi);
    case Tag::kRemoteVersion:
      return mojo::Equals(*(data_.remote_version), *(other.data_.remote_version));
    case Tag::kLocalLeFeatures:
      return mojo::Equals(*(data_.local_le_features), *(other.data_.local_le_features));
  }

  return false;
}
